onClick:
{{
  (async function() {
    let pageSource = appsmith.store.page_precedente;
    const idSource = appsmith.store.id_precedent;

    // Sécurité si une autre page a enregistré le nom sans emoji
    const aliasPages = {
      'Clients': '👥 Clients',
      'Factures': '🧾 Factures',
      'Bon de livraison': '🚚 Bon de livraison',
      'Devis': '📝 Devis',
      'Commandes & Logistique': '🛒 Commandes & Logistique',
      'Location': '🔑 Location'
    };

    if (aliasPages[pageSource]) {
      pageSource = aliasPages[pageSource];
    }

    // Retour par défaut vers la liste Clients si la mémoire est vide
    if (!pageSource || pageSource === 'Détail Client') {
      pageSource = '👥 Clients';
    }

    // Seules les fiches de détail reçoivent le paramètre ?id=...
    const pagesDetail = [
      'Détail Facture',
      'Détail Bon de Livraison',
      'Détail Devis',
      'Détail Commande Client',
      'Détail Intervention',
      'Détail Matériel',
      'Détail Location'
    ];

    if (pagesDetail.includes(pageSource) && idSource) {
      await navigateTo(pageSource, { id: idSource });
    } else {
      await navigateTo(pageSource);
    }
  })()
}}
